async function s(t){const a=await t.arrayBuffer(),e=await crypto.subtle.digest("SHA-256",a),r=new Uint8Array(e);return Array.from(r).map(n=>n.toString(16).padStart(2,"0")).join("")}async function i(t){const e=new TextEncoder().encode(t),r=await crypto.subtle.digest("SHA-256",e),n=new Uint8Array(r);return Array.from(n).map(o=>o.toString(16).padStart(2,"0")).join("")}export{i as a,s};
